    reference: "n = int(input())\nsieve = [True] * (n + 1)\nc = 0\nfor i in range(2, n + 1):\n    if sieve[i]:\n        c += 1\n        for j in range(i * i, n + 1, i):\n            sieve[j] = False\nprint(c)\n",
